/* Econ JMC — English directory of all job market candidates. Data comes from data.js (generated by scripts/build.py):
   D.candidates (China JMC, parsed from data/<cycle>.md) + D.global (data/global/<cycle>.csv). The China JMC module lives in china/. */
(function () {
  "use strict";

  const CONFIG = { repoUrl: "https://github.com/econ-jmc/econ-jmc.github.io" };

  const D = window.JMC_DATA;
  const app = document.getElementById("app");
  if (!D) { app.innerHTML = `<p class="empty">data.js not found — run python scripts/build.py</p>`; return; }
  document.getElementById("generated").textContent = D.generated;
  document.getElementById("repo-link").href = CONFIG.repoUrl;
  const tabsEl = document.getElementById("cycle-tabs");

  const COUNTRY = { "美国区域": "United States", "加拿大区域": "Canada" };
  const PREGION = { "中国大陆": "Mainland China", "港澳": "Hong Kong & Macau", "新加坡": "Singapore", "日本": "Japan", "澳新": "Australia & NZ",
    "加拿大": "Canada", "欧洲": "Europe", "其他": "Other", "美国": "United States" };
  const PLACE_LABEL = { "Faculty": "Faculty", "Non-tenure-track": "Non-tenure-track", "Postdoc": "Postdoc", "Industry & Other": "Industry & other", "Deferred": "Deferred" };

  // one English record per candidate, whatever the source
  const ALL = [
    ...D.candidates.map((c) => ({
      id: c.id, cycle: c.cycle, name: c.name, name_zh: c.name_zh, school: c.school, country: COUNTRY[c.region] || "Other",
      rank: c.rank, order: c.school_order, jmp: c.jmp, fields: c.fields || [], website: c.website, placement: c.placement,
      ptype: c.placement_type, pregion: PREGION[c.placement_region] || null, phd: c.phd_year, research: c.research, china: true,
      education: c.education_en || [],
    })),
    ...(D.global || []).map((g) => ({ ...g, ptype: g.placement_type, pregion: PREGION[g.placement_region] || null, phd: g.phd_year,
      order: 9999, research: null, china: false })),
  ];
  for (const c of ALL) {
    c.skey = c.country + "|" + c.school;
    c.undergrad = (c.education.find((e) => /^b\.?\s?[a-z]|bachelor|^ll\.?b|^b[a-z]{0,3}/i.test(e.degree)) || {}).school || "";
  }
  const BYID = new Map(ALL.map((c) => [c.id, c]));

  // schools per cycle in source order (China JMC lists schools with no candidates too), then schools only in global data
  const SCHOOLS = [];
  const seenSchool = new Set();
  const addSchool = (cycle, name, country, rank, order) => {
    const k = cycle + "|" + country + "|" + name;
    if (seenSchool.has(k)) return;
    seenSchool.add(k);
    SCHOOLS.push({ cycle, name, country, rank, order, key: country + "|" + name });
  };
  for (const s of D.schools) addSchool(s.cycle, s.name, COUNTRY[s.region] || "Other", s.rank, s.order);
  for (const c of ALL) addSchool(c.cycle, c.school, c.country, c.rank, c.order);

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const opt = (v, label, sel) => `<option value="${esc(v)}" ${String(sel) === String(v) ? "selected" : ""}>${esc(label)}</option>`;
  const uniq = (a) => [...new Set(a)];
  const surnameKey = (name) => {
    const parts = String(name).replace(/\([^)]*\)/g, " ").trim().split(/\s+/);
    return (parts[parts.length - 1] + " " + parts.slice(0, -1).join(" ")).toLowerCase();
  };
  const byName = (a, b) => surnameKey(a.name).localeCompare(surnameKey(b.name), "en");
  const cmpSchool = (a, b) => (a.country === b.country ? 0 : a.country === "United States" ? -1 : b.country === "United States" ? 1 : a.country.localeCompare(b.country))
    || (a.rank ?? 9999) - (b.rank ?? 9999) || (a.order ?? 9999) - (b.order ?? 9999) || a.school.localeCompare(b.school);

  // ------------------------------------------------------------ router ----
  function route() {
    const h = location.hash.replace(/^#/, "") || "/";
    const [path, qs] = h.split("?");
    return { parts: path.split("/").filter(Boolean), q: new URLSearchParams(qs || "") };
  }
  function setQuery(base, obj) {
    const q = new URLSearchParams();
    for (const [k, v] of Object.entries(obj)) if (v !== "" && v != null) q.set(k, v);
    const s = q.toString();
    history.replaceState(null, "", "#" + base + (s ? "?" + s : ""));
  }
  function setNav(v) { document.querySelectorAll("#nav a[data-view]").forEach((a) => a.classList.toggle("active", a.dataset.view === v)); }

  // cycle tabs are shared by the candidate, institution and field views
  let cycle = D.cycles[0];
  function renderTabs(show, onPick) {
    tabsEl.hidden = !show;
    if (!show) return;
    tabsEl.innerHTML = [...D.cycles, "all"].map((c) =>
      `<button type="button" data-cycle="${c}" class="${cycle === c ? "active" : ""}">${c === "all" ? "All cycles" : c}</button>`).join("");
    tabsEl.onclick = (e) => { const b = e.target.closest("button[data-cycle]"); if (b) { cycle = b.dataset.cycle; onPick(); } };
  }
  const inCycle = (c) => cycle === "all" || c.cycle === cycle;

  function render() {
    const { parts, q } = route();
    if (q.has("cycle") && (D.cycles.includes(q.get("cycle")) || q.get("cycle") === "all")) cycle = q.get("cycle");
    const v = parts[0] || "";
    if (v === "c") return renderProfile(decodeURIComponent(parts.slice(1).join("/")));
    if (v === "institutions") return renderInstitutions();
    if (v === "fields") return renderFields();
    if (v === "about") return renderAbout();
    return renderCandidates(q);
  }

  // -------------------------------------------------------- candidates ----
  const S = { q: "", country: "", school: "", placement: "", sort: "rank", group: true, fields: new Set() };
  function readS(q) {
    S.q = q.get("q") || ""; S.country = q.get("country") || ""; S.school = q.get("school") || "";
    S.placement = q.get("placement") || ""; S.sort = q.get("sort") || "rank"; S.group = q.get("group") !== "0";
    S.fields = new Set((q.get("fields") || "").split(",").filter(Boolean));
  }
  function writeS() {
    setQuery("/", { cycle: cycle !== D.cycles[0] ? cycle : "", q: S.q, country: S.country, school: S.school, placement: S.placement,
      sort: S.sort !== "rank" ? S.sort : "", group: S.group ? "" : "0", fields: [...S.fields].join(",") });
  }
  function match(c, ign) {
    if (ign !== "country" && S.country && c.country !== S.country) return false;
    if (ign !== "school" && S.school && c.skey !== S.school) return false;
    if (ign !== "placement" && S.placement) {
      if (S.placement === "known" && !c.placement) return false;
      if (S.placement === "unknown" && c.placement) return false;
      if (!["known", "unknown"].includes(S.placement) && c.ptype !== S.placement) return false;
    }
    if (ign !== "fields") for (const f of S.fields) if (!c.fields.includes(f)) return false;
    if (ign !== "q" && S.q) {
      const r = c.research;
      const papers = r ? [...r.publications, ...r.rr, ...r.wp].map((p) => p.title + " " + (p.venue || "") + " " + (p.authors || "")) : [];
      const hay = [c.name, c.school, c.jmp, c.placement, ...c.fields, ...c.education.map((e) => e.school + " " + e.degree), ...papers].join(" ").toLowerCase();
      if (!hay.includes(S.q.toLowerCase())) return false;
    }
    return true;
  }

  function resCounts(c) {
    const r = c.research;
    if (!r) return "";
    const parts = [["Pub", r.publications.length, "pub"], ["R&R", r.rr.length, "rr"], ["WP", r.wp.length, "wp"]]
      .filter(([, n]) => n).map(([l, n, cls]) => `<span class="rc ${cls}"><i></i>${l} ${n}</span>`);
    return parts.length ? `<span class="rcs">${parts.join("")}</span>` : "";
  }
  const placeHtml = (c) => c.placement
    ? `<span class="pl ${esc((c.ptype || "").split(" ")[0])}"><i></i>${esc(PLACE_LABEL[c.ptype] || c.ptype)}</span><span class="txt">${esc(c.placement)}</span>`
    : `<span class="none">–</span>`;
  const fieldsHtml = (c) => c.fields.length ? c.fields.map((f) => `<span>${esc(f)}</span>`).join("") : `<span class="none">–</span>`;

  function candRow(c) {
    const site = c.website ? `<a class="site" href="${esc(c.website)}" target="_blank" rel="noopener" title="${esc(c.website)}">Website ↗</a>` : "";
    const meta = [c.phd ? `PhD ${c.phd}` : "", cycle === "all" ? c.cycle : ""].filter(Boolean).join(" · ");
    const ug = c.undergrad ? `<span class="meta ug" title="Undergraduate">BA · ${esc(c.undergrad)}</span>` : "";
    return `<tr class="cand" data-id="${esc(c.id)}">
      <td class="name"><a class="nm" href="#/c/${encodeURIComponent(c.id)}">${esc(c.name)}</a>
        <span class="meta">${meta}${meta && site ? " · " : ""}${site}</span>${ug}${resCounts(c)}</td>
      <td class="school"><span class="rank">${c.rank ? "#" + c.rank : ""}</span>${esc(c.school)}</td>
      <td class="jmp">${c.jmp ? `<span class="jt">${esc(c.jmp)}</span>` : `<span class="none">–</span>`}</td>
      <td class="fields">${fieldsHtml(c)}</td>
      <td class="place">${placeHtml(c)}</td></tr>`;
  }

  function renderCandidates(q) {
    setNav("candidates");
    readS(q);
    renderTabs(true, () => { S.school = ""; writeS(); renderCandidates(route().q); });
    const pool = ALL.filter(inCycle);
    const list = pool.filter((c) => match(c));
    list.sort(S.sort === "name" ? (a, b) => byName(a, b) || cmpSchool(a, b)
      : S.sort === "school" ? (a, b) => a.school.localeCompare(b.school) || byName(a, b)
      : (a, b) => cmpSchool(a, b) || byName(a, b));
    const grouped = S.group && S.sort === "rank";

    const placed = list.filter((c) => c.placement);
    const n = (t) => placed.filter((c) => c.ptype === t).length;
    const pct = placed.length ? Math.round(100 * n("Faculty") / placed.length) + "%" : "–";
    const filtered = list.length !== pool.length;

    const countries = uniq(pool.map((c) => c.country));
    const schools = uniq(SCHOOLS.filter((s) => (cycle === "all" || s.cycle === cycle) && (!S.country || s.country === S.country))
      .sort((a, b) => cmpSchool({ ...a, school: a.name }, { ...b, school: b.name })).map((s) => s.key));
    const fcount = {};
    for (const c of pool) if (match(c, "fields")) for (const f of c.fields) fcount[f] = (fcount[f] || 0) + 1;
    const cats = D.field_categories.filter((f) => fcount[f] || S.fields.has(f)).sort((a, b) => (fcount[b] || 0) - (fcount[a] || 0));

    let rows = "";
    if (grouped) {
      let last = null;
      for (const c of list) {
        const k = c.cycle + "|" + c.skey;
        if (k !== last) {
          const nIn = list.filter((x) => x.cycle + "|" + x.skey === k).length;
          rows += `<tr class="group"><th colspan="5"><span class="rank">${c.rank ? "#" + c.rank : ""}</span><span class="sn">${esc(c.school)}</span>${c.country !== "United States" ? `<span class="zh">${esc(c.country)}</span>` : ""}${cycle === "all" ? `<span class="zh">${c.cycle}</span>` : ""}<span class="n">${nIn}</span></th></tr>`;
          last = k;
        }
        rows += candRow(c);
      }
    } else rows = list.map(candRow).join("");

    app.innerHTML = `
      <section class="kpis-band">
        <div class="kpi"><div class="n">${list.length}</div><div class="l">Candidates${filtered ? `<span>of ${pool.length}</span>` : ""}</div></div>
        <div class="kpi"><div class="n">${uniq(list.map((c) => c.skey)).length}</div><div class="l">PhD programs</div></div>
        <div class="kpi"><div class="n">${placed.length}</div><div class="l">Known placements
          <span>Faculty ${n("Faculty")}${n("Non-tenure-track") ? ` · NTT ${n("Non-tenure-track")}` : ""} · Postdoc ${n("Postdoc")} · Industry ${n("Industry & Other")}${n("Deferred") ? ` · Deferred ${n("Deferred")}` : ""}</span></div></div>
        <div class="kpi"><div class="n">${pct}</div><div class="l">Of known placements in faculty jobs</div></div>
      </section>
      <section class="controls">
        <div class="row">
          <input id="q" type="search" placeholder="Search name, school, job market paper, education, publications …" autocomplete="off" value="${esc(S.q)}">
          <select id="country">${opt("", "All countries", S.country)}${countries.map((x) => opt(x, `${x} (${pool.filter((c) => c.country === x && match(c, "country")).length})`, S.country)).join("")}</select>
          <select id="school">${opt("", "All PhD programs", S.school)}${schools.map((k) => {
            const s = SCHOOLS.find((x) => x.key === k);
            return opt(k, `${s.rank ? "#" + s.rank + " " : ""}${s.name} (${pool.filter((c) => c.skey === k && match(c, "school")).length})`, S.school);
          }).join("")}</select>
          <select id="placement">${[["", "All placements"], ["known", "Placement known"], ["Faculty", "Faculty"], ["Non-tenure-track", "Non-tenure-track faculty"],
            ["Postdoc", "Postdoc"], ["Industry & Other", "Industry & other"], ["Deferred", "Deferred"], ["unknown", "Placement unknown"]].map(([v, l]) => opt(v, l, S.placement)).join("")}</select>
          <select id="sort">${[["rank", "Sort by program rank"], ["name", "Sort by surname"], ["school", "Sort by program name"]].map(([v, l]) => opt(v, l, S.sort)).join("")}</select>
          <label class="toggle"><input type="checkbox" id="group" ${S.group ? "checked" : ""}> Group by program</label>
          <button id="reset" class="btn-ghost" type="button">Clear filters</button>
        </div>
        <div class="row chips" id="chips">${cats.map((f) =>
          `<button type="button" class="chip ${S.fields.has(f) ? "active" : ""}" data-field="${esc(f)}">${esc(f)}<span class="c">${fcount[f] || 0}</span></button>`).join("")}</div>
      </section>
      <p class="result-count">${filtered ? `${list.length} of ${pool.length} candidates` : `${pool.length} candidates${cycle === "all" ? " across all cycles" : ` in the ${cycle} cycle`}`}</p>
      <section class="table-wrap">
        <table class="${grouped ? "grouped" : ""}">
          <thead><tr><th class="col-name">Name</th><th class="col-school">PhD program</th><th class="col-jmp">Job market paper</th><th class="col-fields">Fields</th><th class="col-place">Placement</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
        ${list.length ? "" : `<p class="empty">No candidates match these filters.</p>`}
      </section>`;

    const rerender = () => { writeS(); renderCandidates(route().q); };
    const $ = (id) => document.getElementById(id);
    let t;
    $("q").oninput = () => { clearTimeout(t); t = setTimeout(() => { S.q = $("q").value.trim(); writeS(); renderCandidates(route().q); const i = $("q"); i.focus(); i.setSelectionRange(i.value.length, i.value.length); }, 150); };
    $("country").onchange = () => { S.country = $("country").value; S.school = ""; rerender(); };
    $("school").onchange = () => { S.school = $("school").value; rerender(); };
    $("placement").onchange = () => { S.placement = $("placement").value; rerender(); };
    $("sort").onchange = () => { S.sort = $("sort").value; rerender(); };
    $("group").onchange = () => { S.group = $("group").checked; rerender(); };
    $("reset").onclick = () => { Object.assign(S, { q: "", country: "", school: "", placement: "", sort: "rank", group: true, fields: new Set() }); rerender(); };
    $("chips").onclick = (e) => {
      const b = e.target.closest("button[data-field]");
      if (!b) return;
      S.fields.has(b.dataset.field) ? S.fields.delete(b.dataset.field) : S.fields.add(b.dataset.field);
      rerender();
    };
    app.querySelectorAll("tr.cand").forEach((tr) => tr.onclick = (e) => { if (!e.target.closest("a")) location.hash = "#/c/" + encodeURIComponent(tr.dataset.id); });
  }

  // ----------------------------------------------------------- profile ----
  const RES_GROUPS = [["publications", "Publications", "pub"], ["rr", "Revise & Resubmit", "rr"], ["wp", "Working Papers", "wp"]];
  function paperItem(p) {
    const notes = (p.note || "").split(/\s*;\s*/).filter(Boolean);
    const isJmp = notes.some((n) => /\bJMP\b/.test(n));
    const rest = notes.map((n) => n.replace(/^\(?JMP\b\)?[\s:,–-]*/, "").replace(/^\((.*)\)$/, "$1").trim()).filter(Boolean);
    const title = p.url ? `<a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)}</a>` : esc(p.title);
    const meta = [p.authors ? `with ${esc(p.authors)}` : "", p.venue ? `<em>${esc(p.venue)}</em>` : "", p.year || "",
      ...rest.map((n) => `<span class="pn">${esc(n)}</span>`)].filter(Boolean).join(" · ");
    return `<li><span class="pt">${title}</span>${isJmp ? `<span class="jmp-tag">JMP</span>` : ""}${meta ? `<span class="pm">${meta}</span>` : ""}</li>`;
  }

  function renderProfile(id) {
    setNav("candidates");
    renderTabs(false);
    const c = BYID.get(id);
    if (!c) { app.innerHTML = `<p class="crumb"><a href="#/">← Candidates</a></p><p class="empty">Candidate not found.</p>`; return; }
    const r = c.research;
    const groups = r ? RES_GROUPS.filter(([k]) => r[k].length).map(([k, label, cls]) =>
      `<div class="r-group ${cls}"><div class="r-label"><i></i>${label}<span>${r[k].length}</span></div><ul class="papers">${r[k].map(paperItem).join("")}</ul></div>`).join("") : "";
    const src = c.china ? `data/${esc(c.cycle)}.md` : `data/global/${esc(c.cycle)}.csv`;
    app.innerHTML = `
      <p class="crumb"><a href="#/?cycle=${c.cycle}">Candidates</a> / <a href="#/?cycle=${c.cycle}&school=${encodeURIComponent(c.skey)}">${esc(c.school)}</a> / ${esc(c.name)}</p>
      <article class="profile">
        <h2>${esc(c.name)}</h2>
        <p class="sub">${c.rank ? `<span class="rank">#${c.rank}</span> ` : ""}${esc(c.school)}${c.country !== "United States" ? `, ${esc(c.country)}` : ""} · ${esc(c.cycle)} job market${c.phd ? ` · PhD ${c.phd}` : ""}
          ${c.website ? ` · <a href="${esc(c.website)}" target="_blank" rel="noopener">Website ↗</a>` : ""}</p>
        <dl class="facts">
          <div><dt>Job market paper</dt><dd>${c.jmp ? `<span class="jt">${esc(c.jmp).replace(/ \| /g, "<br>")}</span>` : `<span class="none">–</span>`}</dd></div>
          <div><dt>Fields</dt><dd class="fields">${c.fields.length ? c.fields.map((f) => `<a href="#/?cycle=${c.cycle}&fields=${encodeURIComponent(f)}">${esc(f)}</a>`).join(" · ") : `<span class="none">–</span>`}</dd></div>
          <div><dt>Education</dt><dd>${c.education.length ? `<ul class="edu">${c.education.map((e) =>
            `<li><span class="yr">${e.year || ""}</span><span>${esc(e.degree)}${e.school ? `, <b>${esc(e.school)}</b>` : ""}</span></li>`).join("")}</ul>` : `<span class="none">–</span>`}</dd></div>
          <div><dt>Placement</dt><dd class="place">${placeHtml(c)}${c.pregion ? `<span class="txt muted">${esc(c.pregion)}</span>` : ""}</dd></div>
        </dl>
        ${r ? `<div class="research"><h4>Research</h4>${groups || `<p class="none">No papers listed on the website.</p>`}
          <p class="src">From the candidate's ${r.source ? `<a href="${esc(r.source.split(/\s|,/)[0])}" target="_blank" rel="noopener">website</a>` : "website"}${r.checked ? `, checked ${esc(r.checked)}` : ""}; paper status as listed there.</p></div>` : ""}
        <p class="src">Source: ${src} · <a href="${CONFIG.repoUrl}/edit/main/${src}" target="_blank" rel="noopener">Suggest an edit</a>${c.china ? ` · Also listed in <a href="china/#cycle=${c.cycle}&q=${encodeURIComponent(c.name)}" lang="zh-CN">China JMC</a>` : ""}</p>
      </article>`;
  }

  // ------------------------------------------------------ institutions ----
  function renderInstitutions() {
    setNav("institutions");
    renderTabs(false);
    const keys = uniq(SCHOOLS.map((s) => s.key));
    const info = new Map();
    for (const s of SCHOOLS) if (!info.has(s.key) || (s.rank && !info.get(s.key).rank)) info.set(s.key, s);
    const rows = keys.map((k) => {
      const cs = ALL.filter((c) => c.skey === k);
      const placed = cs.filter((c) => c.placement);
      return { s: info.get(k), cs, placed, fac: placed.filter((c) => c.ptype === "Faculty").length };
    }).sort((a, b) => cmpSchool({ ...a.s, school: a.s.name }, { ...b.s, school: b.s.name }));
    app.innerHTML = `
      <h2 class="view-h">PhD programs</h2>
      <p class="intro">Candidates on the market from each program, by cycle. Click a program to list its candidates.</p>
      <section class="table-wrap"><table class="inst">
        <thead><tr><th class="num">#</th><th>Program</th><th>Country</th>${D.cycles.map((y) => `<th class="num">${y}</th>`).join("")}<th class="num">Total</th><th class="num">Known placements</th><th class="num">Faculty</th></tr></thead>
        <tbody>${rows.map(({ s, cs, placed, fac }) => `<tr class="clk" data-key="${esc(s.key)}">
          <td class="num rank">${s.rank ?? ""}</td><td><a href="#/?cycle=all&school=${encodeURIComponent(s.key)}"><b>${esc(s.name)}</b></a></td><td class="muted">${esc(s.country)}</td>
          ${D.cycles.map((y) => { const n = cs.filter((c) => c.cycle === y).length; return `<td class="num">${n || `<span class="none">·</span>`}</td>`; }).join("")}
          <td class="num"><b>${cs.length}</b></td><td class="num">${placed.length}</td><td class="num">${placed.length ? fac + ` <span class="muted">(${Math.round(100 * fac / placed.length)}%)</span>` : ""}</td></tr>`).join("")}</tbody>
      </table></section>`;
    app.querySelectorAll("tr.clk").forEach((tr) => tr.onclick = (e) => { if (!e.target.closest("a")) location.hash = "#/?cycle=all&school=" + encodeURIComponent(tr.dataset.key); });
  }

  // ------------------------------------------------------------ fields ----
  function renderFields() {
    setNav("fields");
    renderTabs(true, () => { setQuery("/fields", { cycle: cycle !== D.cycles[0] ? cycle : "" }); renderFields(); });
    const pool = ALL.filter(inCycle);
    const cnt = (f, list) => list.filter((c) => c.fields.includes(f)).length;
    const cats = D.field_categories.slice().sort((a, b) => cnt(b, pool) - cnt(a, pool));
    const max = Math.max(1, ...cats.map((f) => cnt(f, pool)));
    app.innerHTML = `
      <h2 class="view-h">Fields</h2>
      <p class="intro">Research fields of ${cycle === "all" ? "all" : "the " + cycle} candidates (a candidate can list several). Click a field to list its candidates.</p>
      <div class="fgrid">${cats.map((f) => {
        const list = pool.filter((c) => c.fields.includes(f));
        const placed = list.filter((c) => c.placement);
        const fac = placed.filter((c) => c.ptype === "Faculty").length;
        return `<a class="fcell" href="#/?cycle=${cycle}&fields=${encodeURIComponent(f)}">
          <span class="fn">${esc(f)}</span><span class="c">${list.length}</span>
          <span class="bar"><i style="width:${(100 * list.length / max).toFixed(1)}%"></i></span>
          <span class="fs">${placed.length ? `${fac} of ${placed.length} known placements in faculty jobs` : "No placements yet"}</span></a>`;
      }).join("")}</div>`;
  }

  // ------------------------------------------------------------- about ----
  function renderAbout() {
    setNav("about");
    renderTabs(false);
    const nCn = D.candidates.length, nG = (D.global || []).length;
    app.innerHTML = `
      <article class="about">
        <h2 class="view-h">About Econ JMC</h2>
        <p><b>Econ JMC</b> is an open, community-maintained directory of economics PhD job market candidates: where they trained, their job market papers and fields, their research, and where they were placed. It currently lists <b>${ALL.length}</b> candidates from ${D.cycles.length} job market cycles (${D.cycles.slice().reverse().join(", ")}).</p>
        <h3>Coverage</h3>
        <p>The directory started from <a href="china/" lang="zh-CN">China JMC</a> (${nCn} candidates): economics PhD candidates from mainland China at US and Canadian programs, compiled in Chinese every cycle since 2024. We are expanding it to <b>all</b> economics job market candidates${nG ? ` (${nG} more so far)` : ""}. Coverage of other candidates is still partial, so counts on this site are not yet representative of the whole market.</p>
        <h3>China JMC · 中国经济学博士求职者名录</h3>
        <p>The original Chinese-language directory, with candidate bios, education and a placement statistics report, continues as its own module: <a href="china/">China JMC</a> · <a href="china/stats.html">placement statistics</a>.</p>
        <h3>Contributing</h3>
        <p>Data live in the <a href="${CONFIG.repoUrl}" target="_blank" rel="noopener">GitHub repository</a>. Add candidates for any program to <code>data/global/&lt;cycle&gt;.csv</code> (columns: name, school, country, school_rank, jmp, fields, website, placement; see <code>data/global/_template.csv</code>); China JMC entries are edited in <code>data/&lt;cycle&gt;.md</code>. The site rebuilds automatically on every commit.</p>
        <p>Candidates may request corrections or removal of their entry by opening an issue. All information is compiled from public personal websites and department placement pages.</p>
      </article>`;
  }

  window.addEventListener("hashchange", render);
  render();
})();
